# ============= tests/test_core/test_eto_calculator.py =============\n\"\"\"Tests for ETO Calculator\"\"\"\nimport pytest\nfrom src.core.eto_calculator import ETOCalculator\n\n\ndef test_calculate_eto_basic():\n    \"\"\"Test basic ETo calculation\"\"\"\n    eto = ETOCalculator.calculate_eto(\n        tmin=15.0,\n        tmax=25.0,\n        rhmin=50,\n        rhmax=80,\n        wind_speed=2.0,\n        sunshine_hours=8,\n        latitude=-1.94,\n        elevation=1500,\n        day_of_year=150\n    )\n    assert eto > 0\n    assert eto < 10  # Reasonable range for daily ETo\n\n\ndef test_calculate_eto_extreme():\n    \"\"\"Test ETo with extreme values\"\"\"\n    eto = ETOCalculator.calculate_eto(\n        tmin=0.0,\n        tmax=10.0,\n        rhmin=20,\n        rhmax=40,\n        wind_speed=0.5,\n        sunshine_hours=2,\n        latitude=-1.94,\n        elevation=1500,\n        day_of_year=1\n    )\n    assert eto >= 0  # Should not be negative
